def fizz_buzz(n: int):
    count = 0
    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def strange_sort_list(lst):
    lst.sort()
    result = []
    while lst:
        result.append(lst.pop(0))
        if lst:
            result.append(lst.pop())
    return result

def sort_array(array):
    if not array:
        return []
    else:
        sum_val = array[0] + array[-1]
        if sum_val % 2 == 0:
            return sorted(array, reverse=True)
        else:
            return sorted(array)

def largest_smallest_integers(lst):
    neg_nums = [i for i in lst if i < 0]
    pos_nums = [i for i in lst if i > 0]

    if not neg_nums:
        max_neg = None
    else:
        max_neg = max(neg_nums)

    if not pos_nums:
        min_pos = None
    else:
        min_pos = min(pos_nums)

    return (max_neg, min_pos)

from typing import List, Tuple

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []
    max_nums = [numbers[0]]
    for num in numbers[1:]:
        max_nums.append(max(max_nums[-1], num))
    return max_nums

def get_odd_collatz(n):
    collatz = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        collatz.append(n)

    return sorted([num for num in collatz if num % 2 != 0])

def fib(n: int):
    if n <= 0:
        return "Input should be positive integer."
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        a, b = 1, 1
        for _ in range(n - 2):
            a, b = b, a + b
        return b

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]
    return ""

