def is_simple_power(x, n):
    if n == 1:
        return x == 1
    while x > 1:
        x /= n
        if x == int(x):
            continue
        else:
            return False
    return True

def make_a_pile(n):
    if n % 2 == 0:
        return [n + i for i in range(0, n, 2)]
    else:
        return [n + i for i in range(1, n, 2)]

def how_many_times(string: str, substring: str) -> int:
    count = start = 0
    while start < len(string):
        pos = string.find(substring, start)
        if pos != -1:
            start = pos + 1
            count += 1
        else:
            break
    return count

def x_or_y(n, x, y):
    if n > 1:
        for i in range(2, n):
            if (n % i) == 0:
                return y
        return x
    else:
        return y
